  q.p([X(-6),Y(-5),X(0),Y(-5),X(0),Y(6),X(-6),Y(6)],.93,.5,.3); for(let i=1;i<10;i++) q.l(X(-6),Y(-5+i*1.1),X(0),Y(-5+i*1.1),.3,.4); q.t(X(-3),Y(.5),'Rampe 15 %',Math.max(6,S*.32),0,1,90);
  q.t(X(14),Y(3),'Circulation '+(o.places||24)+' places, largeur 6.00 m',Math.max(6.5,S*.38),2,1);
  q.r(X(13),Y(6.6),4*S,4.8*S,.92,.25*S,enc); q.t(X(15),Y(8.8),'Cage',Math.max(5.5,S*.3),0,1);
