  for(let i=0;i<6;i++){ q.r(X(17+i*2.1),Y(15.5),2.1*S,4.5*S,null,.4,.2); q.t(X(17+i*2.1+1.05),Y(17.6),'Cave '+(i+13),Math.max(5,S*.24),2,1); }
  q.r(X(17),Y(11),6.5*S,4.5*S,null,.8,.2); q.t(X(20.2),Y(13),'Local technique',Math.max(6,S*.3),0,1); q.r(X(23.5),Y(11),6.5*S,4.5*S,null,.8,.2); q.t(X(26.7),Y(13),'Abri / rangement',Math.max(6,S*.3),0,1); q.t(X(-3),Y(13),'Réserve',Math.max(6,S*.3),2,1);
  if(o.places>22){ q.r(X(30),Y(-5),6.5*S,5*S,null,.5,.2); q.t(X(33.2),Y(-2.7),'Locaux communs',Math.max(5.5,S*.26),2,1); }
  if(o.cotes){ const ya=Y(-6.6); for(let i=0;i<4;i++) cote(q,X(i*7.5),ya,X((i+1)*7.5),ya,'7.50'); if(o.places>22) cote(q,X(30),ya,X(37.5),ya,'7.50'); cote(q,X(-7.5),Y(-5),X(-7.5),Y(20),'25.00'); }
