  if(o.remplacement) [[33,1.5],[39,1.3],[45,1.1],[51,.9],[57,.7],[63,.5],[5,6],[66,5]].forEach(([x,y])=>q.c(X(x),Y(y),Math.max(3,1.6*S),[.72,.86,.66],.8,[.2,.5,.2]));
