/* altitudes du relevé : terrain en pente douce vers le sud-est */
const altitude=(x,y)=>517.9+.046*y-.008*x+.018*Math.sin(x/9)*y/4;
function releve(q,V){ const X=V.X, Y=V.Y, S=V.S; for(let x=4;x<68;x+=9) for(let y=3;y<30;y+=7.5){ const a=altitude(x,y); q.c(X(x),Y(y),1.2,0); q.t(X(x)+3,Y(y)-2.5,nb(a,2),Math.max(5.5,S*.58),0); }
  for(let k=0;k<6;k++){ const h=518+k*.25, T=[]; for(let x=-2;x<=70;x+=4){ let y=(h-517.9+.008*x)/.046; T.push(X(x),Y(Math.max(-1,Math.min(34,y-.4*Math.sin(x/9)*y/4)))); } q.p(T,null,.35,[.65,.45,.25],0); } }
