/* ═══ 41 APPELS D'OFFRES ═══ */
function c41(ctx,F,B){ const {R,C,DIR,PRES,MO,LOT,net,orgE,orgM,orgC,offres,bureau,sig,dgHT,t8,cor}=F, {L,D,T,P,J,cdp,dt,te,de}=B, ph='Appels d’offres', ent=k=>ctx.ent[k], titreAO='Appel d’offres';
  const invit=(k)=>{ const l=LOT(k), e=ent(k); L(l.ao.envoi,'41/Correspondance',`Lettre_Invitation_a_soumissionner_CFC_${k}`,e[0].pers.contact,`Invitation à soumissionner, CFC ${l.bkp} ${l.lib}`,[
    `Mandatés par ${MO.nom}, nous vous invitons à présenter une offre pour les travaux du CFC ${l.bkp} ${l.lib} de l’immeuble de 18 logements du ${R.adresse.rue}, à ${R.lieu}.`,
    `Le dossier ci-joint comprend le descriptif, les plans et les conditions particulières, avec les charges du permis de construire. Procédure sur invitation, offres à remettre sous pli fermé.`,
    `Votre offre doit nous parvenir au plus tard le ${long(l.ao.retour)} à 11 h. Travaux prévus du ${fr(l.trav[0])} au ${fr(l.trav[1])}. Une visite des lieux a lieu sur demande.`],{titre:titreAO,cfc:l.bkp,cfcTexte:l.lib,adjoints:e.slice(1).map(x=>x.pers.contact)}); };
  ['112','211','221'].forEach(invit);
  const adj=(k,par=cdp)=>{ const l=LOT(k), e=ent(k)[0]; L(l.adj,'41/Correspondance',`Lettre_Adjudication_CFC_${k}_${e.nom}`,e.pers.contact,`Adjudication, CFC ${l.bkp} ${l.lib}`,[
    `Sur notre proposition, ${MO.nom} vous adjuge les travaux du CFC ${l.bkp} ${l.lib}.`,
    `Montant brut ${chf(l.contrat)} HT${l.R?`, rabais ${l.R} %`:''}${l.E?`, escompte ${l.E} %`:''}${l.prorata?`, prorata ${l.prorata} %`:''}, soit net ${chf(net(l))} HT, TVA ${R.tva} % en sus.`,
    `Le contrat d’entreprise vous parvient en deux exemplaires. Début des travaux le ${long(l.trav[0])}, fin le ${long(l.trav[1])}.${l.contrat>=100000?' Une garantie bancaire d’exécution est exigée pour ce montant.':''}`],{titre:'Lettre d’adjudication',cfc:l.bkp,cfcTexte:l.lib,par}); };
  ['112','201','211','221','232'].forEach(k=>adj(k));
  const refus=k=>{ const l=LOT(k), e=ent(k).slice(1); L(ouvre(A.plus(l.adj,3)),'41/Correspondance',`Lettre_Refus_CFC_${k}`,e[0].pers.contact,`Appel d’offres, CFC ${l.bkp} ${l.lib}`,[
    `Nous vous remercions de votre offre pour les travaux du CFC ${l.bkp} ${l.lib}, ainsi que du temps consacré à son étude.`,
    `Après comparaison selon les critères annoncés, soit le prix, les références, l’organisation et les délais, ${MO.nom} a adjugé ces travaux à une autre entreprise.`,
    `Nous espérons avoir l’occasion de vous consulter pour d’autres projets.`],{titre:'Lettre de refus',cfc:l.bkp,cfcTexte:l.lib,adjoints:e.slice(1).map(x=>x.pers.contact)}); };
  ['211','221'].forEach(refus);
  /* offres d'entreprises, sur leur papier */
  const offre=(k,i,d)=>T(d,'41/Offres',`Offre_CFC_${k}_${ent(k)[i].nom}`,orgE(k,i),`Offre, CFC ${LOT(k).bkp} ${LOT(k).lib}`,[...offreBlocs(F,k,i,d),{k:'signature',cols:[sig('Pour l’entreprise',ent(k)[i].pers.nom,20+i)]}],{dest:bureau,lieu:orgE(k,i).lieu,par:te,ref:'Offre '+d.slice(2,4)+'-'+String(k).padStart(3,'0')+'/'+(i+1)});
  [['112',0],['112',1],['211',0],['211',1],['211',2],['221',0],['221',1],['232',0]].forEach(([k,i])=>{ const l=LOT(k), r=A.prochainOuvre(A.plus(l.ao.retour,-2-i)); offre(k,i,r); });
  J('2024-11-13','41/Photos','Visite_des_lieux_soumissionnaires',{saison:'automne',hangar:1},{par:te});
  T('2024-11-04','41/Géomètre','Plan_des_limites_pour_les_soumissionnaires',orgM('geom'),'Note aux soumissionnaires, limites et points fixes',[para(`Les points de limite de la parcelle ${R.parcelle} ont été retrouvés. Deux points fixes altimétriques sont posés sur le chemin : ils servent de référence à toutes les entreprises.`),tab(['Point|30','Altitude m|30|r','Situation|40'],[['PF1','518.12','Bordure du chemin, angle sud-ouest'],['PF2','518.47','Bordure du chemin, angle sud-est']]),{k:'signature',cols:[sig('L’ingénieure géomètre',ctx.mand.geom.pers.nom,10)]}],{dest:bureau,lieu:F.mand('geom').loc,par:te});
  T('2024-11-15','41/Ingénieurs CVSE','Cahier_des_charges_CVSE',orgM('cvse'),'Cahier des charges des lots techniques',[para('Pièce commune aux appels d’offres des CFC 232, 242, 244 et 251.'),tab(['Lot|12','Exigence particulière|88'],[['232','Bornes de recharge préparées, comptage centralisé au sous-sol'],['242','Pompe à chaleur capotée, puissance acoustique garantie par le fournisseur'],['244','Clapets coupe-feu selon la synthèse CAMAC'],['251','Colonnes groupées, manchons acoustiques']]),{k:'signature',cols:[sig('L’ingénieur CVS',ctx.mand.cvse.pers.nom,5)]}],{dest:bureau,lieu:F.mand('cvse').loc,par:te});
  T('2024-11-22','41/Ingénieur civil','Conditions_techniques_gros_oeuvre',orgM('ing'),'Conditions techniques du gros œuvre',[para(`Annexe à l’appel d’offres du CFC ${LOT('211').bkp}.`),tab(['Thème|30','Condition|70'],[['Bétons','C30/37 XC2 en général, C30/37 XC4 pour les parties extérieures'],['Coffrages','Type 2 en sous-sol, type 3 dans les cages'],['Armature','Réception par l’ingénieur avant chaque bétonnage, annonce 48 heures à l’avance'],['Étanchéité','Radier et murs enterrés en béton étanche, joints équipés']]),{k:'signature',cols:[sig('L’ingénieur civil',ctx.mand.ing.pers.nom,8)]}],{dest:bureau,lieu:F.mand('ing').loc,par:te});
  T('2024-11-29','41/Autorisations','Charges_du_permis_pour_les_soumissions',orgC,'Charges du permis à reprendre dans les soumissions',[para(`Le service technique vous rappelle les charges du permis n° ${F.noCom} qui concernent les entreprises.`),tab(['Charge|70','Lots|30'],[['Travaux bruyants de 8 h à 12 h et de 13 h à 17 h, jours ouvrables seulement','Tous'],['Bordereaux de suivi des déchets à remettre à la commune','112, 201'],['Plantations indigènes en pleine terre','421']]),{k:'signature',cols:[sig('Le chef du service technique',F.CHEF.nom,7)]}],{dest:bureau,lieu:R.lieu,par:te});
  T('2024-12-06','41/Physique du bâtiment','Exigences_pour_les_soumissions',orgM('phys'),'Exigences de physique du bâtiment pour les soumissions',[tab(['Lot|12','Exigence|88'],[['221','Fenêtres : Uw ≤ 0.90 W/m²K, Rw + Ctr selon concept acoustique'],['224','Isolation de toiture : U ≤ 0.15 W/m²K'],['226','Isolation de façade : U ≤ 0.17 W/m²K, traitement des ponts thermiques aux balcons'],['273','Portes palières : Rw 37 dB']]),{k:'signature',cols:[sig('La physicienne du bâtiment',ctx.mand.phys.pers.nom,6)]}],{dest:bureau,lieu:F.mand('phys').loc,par:te});
  P('2024-11-11','41/Plans','S01_Plan_de_soumission_gros_oeuvre',PL=>PL.sousSol(CT(F,'Plan de soumission, gros œuvre, sous-sol','S01','1:100','0','2024-11-11',B.de,cdp,ph,{statut:'POUR APPEL D’OFFRES'}),{places:24}),{par:te});
  const lignes=R.lots.filter(l=>l.contrat!=null).map(l=>{ const dg=l.dg.reduce((a,x)=>a+x.ht,0); return [l.lot,l.lib,ctx.ent[l.k][0].nom,nb(dg,2),nb(l.contrat,2),nb(l.contrat-dg,2)]; });
  D(R.lots.filter(l=>l.adj).map(l=>l.adj).sort().pop(),'41/Documents','Tableau_des_adjudications','Tableau des adjudications',[h1('Adjudications par lot'),tab(['CFC|9','Lot|24','Adjudicataire|30','Devis général|14|r|m','Contrat brut|14|r|m','Écart|10|r|m'],lignes),para('Montants HT en CHF. Tableau tenu à jour à chaque adjudication, dernière adjudication incluse.')],{paysage:1,par:te});
  const o211=offres('211');
  D('2025-02-24','41/Présentation client','Comparatif_du_gros_oeuvre','Comparatif du gros œuvre',[h1('Adjudication du gros œuvre, séance du '+long('2025-02-24')),tab(['Entreprise|44','Offre brute HT|20|r|m','Appréciation|36'],o211.map((o,i)=>[o.nom,nb(o.brut,2),i===0?'Proposée : références et organisation':i===1?'Organisation de chantier plus faible':'Offre la plus chère'])),para(`Proposition : ${o211[0].nom}, contrat brut de ${chf(LOT('211').contrat)} HT, sous le montant du devis général.`)],{paysage:1,par:te}); }

/* lecture du contrôle des coûts quand m47 a tourné : avenant d'entreprise par sa désignation, décompte par lot */
const ccDoc=ctx=>{ try{ return ctx.couts&&ctx.couts.cc?DS.get('costcontrol',ctx.couts.cc):null; }catch(_){ return null; } };
const avenantHT=(ctx,re,def)=>{ const C=ccDoc(ctx), a=C&&(C.contrats||[]).find(x=>x.type==='avenant'&&re.test(x.designation||'')); return a?(a.lignes||[]).reduce((s,l)=>s+(+l.brut||0),0):def; };
const decompteLot=(ctx,l)=>{ const C=ccDoc(ctx), e=ctx.ent[l.k][0], r={contrat:l.contrat,avenants:0,final:null}; if(!C) return r; const c=(C.contrats||[]).find(x=>x.type==='contrat'&&x.contactId===e.contact); if(!c) return r;
  r.avenants=(C.contrats||[]).filter(x=>x.contratParentId===c.id).reduce((s,x)=>s+(x.lignes||[]).reduce((u,y)=>u+(+y.brut||0),0),0); const a=(C.arretes||[]).find(x=>x.contratId===c.id||x.contactId===e.contact); if(a) r.final=+a.ht||null; return r; };
/* montant d'une facture : celui de Facturation quand m30 a tourné, sinon le calcul de REF */
const montantFacture=(F,num)=>{ const {R,M}=F, D=typeof fxData==='function'?fxData():null, f=D&&(D.f||[]).find(x=>x.num===num); if(f){ const t=(+f._ttc||0)+(+f._fttc||+f.fttc||0); if(t>0) return t; }
  const i=R.factures.findIndex(x=>x.num===num), s=o=>Object.values(o||{}).reduce((a,b)=>a+b,0), av=R.factures.slice(0,i).filter(x=>x.phases&&x.contrat==='mandat').pop(); return (s(R.factures[i].phases)-s(av&&av.phases))/100*M.v2.hht*(1+M.frais/100)*(1+R.tva/100); };

